mapper.select:
SELECT COUNT(*) FROM board_post bp INNER JOIN board_category bc ON bp.seqCategory = bc.seqCategory INNER JOIN member m ON bp.seqMember = m.seqMember WHERE bp.status = 'NORMAL'
AND bc.categoryName = #{category}
AND ( LOWER(bp.title) LIKE '%' || LOWER(#{searchWord}) || '%' OR LOWER(bp.content) LIKE '%' || LOWER(#{searchWord}) || '%' )

SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY bp.SEQBOARDPOST DESC) AS rnum, bp.SEQBOARDPOST, bp.SEQCATEGORY, bp.SEQMEMBER, bp.TITLE, bp.CONTENT, bp.VIEWCOUNT, bp.STATUS, TO_CHAR(bp.CREATEDATE, 'YYYY-MM-DD') AS createDate, TO_CHAR(bp.UPDATEDATE, 'YYYY-MM-DD') AS updateDate, bc.CATEGORYNAME AS categoryName, m.NAME AS writerName, f.SAVEDNAME AS savedName FROM BOARD_POST bp INNER JOIN BOARD_CATEGORY bc ON bp.SEQCATEGORY = bc.SEQCATEGORY INNER JOIN MEMBER m ON bp.SEQMEMBER = m.SEQMEMBER LEFT JOIN ( SELECT SEQBOARDPOST, SAVEDNAME, ROW_NUMBER() OVER (PARTITION BY SEQBOARDPOST ORDER BY SEQBOARDPOSTFILE ASC) AS file_rnum FROM BOARD_POST_FILE ) f ON bp.SEQBOARDPOST = f.SEQBOARDPOST AND f.file_rnum = 1 WHERE bp.STATUS = 'NORMAL'
AND bc.CATEGORYNAME = #{category}
AND ( LOWER(bp.TITLE) LIKE '%' || LOWER(#{searchWord}) || '%' OR LOWER(bp.CONTENT) LIKE '%' || LOWER(#{searchWord}) || '%' )
) WHERE rnum BETWEEN #{begin} AND #{end}

mapper.update:
UPDATE board_post
SET viewCount = viewCount + 1
WHERE seqBoardPost = #{seqBoardPost}

mapper.select:
SELECT seqMember
FROM board_post
WHERE seqBoardPost = #{seqBoardPost}
